INSERT INTO "methodology_documents"
  ("domain", "version", "status", "parameters", "guidance", "justifications", "change_note", "eval_run_ids", "published_at")
SELECT 'STRENGTH', 1, 'PUBLISHED', $mv${"intensity": {"repsByGoal": {"HYPERTROPHY": {"reps": {"max": 15, "min": 6}}, "MUSCULAR_ENDURANCE": {"reps": {"max": 20, "min": 10}}, "STRENGTH": {"reps": {"max": 6, "min": 3}}}, "restSeconds": {"COMPOUND": {"seconds": {"max": 180, "min": 120}}, "ISOLATION": {"seconds": {"max": 120, "min": 60}}, "STRENGTH_MAIN": {"seconds": {"max": 300, "min": 180}}}, "rirByPhase": {"ADAPTATION": {"rir": {"max": 5, "min": 3}}, "DELOAD": {"rir": {"max": 5, "min": 4}}, "HYPERTROPHY": {"rir": {"max": 3, "min": 1}}, "STRENGTH": {"rir": {"max": 3, "min": 2}}}}, "periodization": {"blockWeeksByPhase": {"ADAPTATION": {"weeks": {"max": 4, "min": 2}}, "DELOAD": {"weeks": {"max": 2, "min": 1}}, "HYPERTROPHY": {"weeks": {"max": 8, "min": 4}}, "STRENGTH": {"weeks": {"max": 6, "min": 3}}}, "deloadEveryWeeks": {"ADVANCED": {"weeks": 6}, "BEGINNER": {"weeks": 8}, "INTERMEDIATE": {"weeks": 7}}, "deloadVolumeReductionPct": 40, "loadIncrementKg": {"LOWER": {"kg": {"max": 5, "min": 2.5}}, "UPPER": {"kg": {"max": 2.5, "min": 1}}}, "progressionMethod": "DOUBLE_PROGRESSION"}, "structure": {"allowedSplits": {"ADVANCED": {"bodyPart": true, "fullBody": true, "pushPullLegs": true, "upperLower": true}, "BEGINNER": {"bodyPart": true, "fullBody": true, "pushPullLegs": false, "upperLower": true}, "INTERMEDIATE": {"bodyPart": true, "fullBody": true, "pushPullLegs": true, "upperLower": true}}, "compoundFirst": true, "maxExercisesPerSession": 7}, "volume": {"maxSetsPerMusclePerSession": 8, "minFrequencyPerMuscle": 2, "weeklySets": {"ADVANCED": {"sets": {"max": 20, "min": 10}}, "BEGINNER": {"sets": {"max": 10, "min": 6}}, "INTERMEDIATE": {"sets": {"max": 14, "min": 8}}}}}$mv$::jsonb, $mv${"exerciseSelection": "A seleção de exercícios na MOVIVO começa pelo objetivo do treino e pelos padrões de movimento necessários para alcançá-lo, utilizando-os como estrutura para desenvolver força, hipertrofia e capacidade funcional. A escolha considera os grupos musculares prioritários, a amplitude de movimento, a estabilidade, a exigência técnica, o conforto articular, a experiência do aluno e os equipamentos disponíveis. Cada exercício deve ter uma função clara dentro do programa, evitando redundâncias e favorecendo uma distribuição eficiente do estímulo.\n\nMáquinas, pesos livres e peso corporal são ferramentas, não hierarquias de qualidade. Máquinas podem ser preferidas quando oferecem estabilidade, facilidade de execução ou estímulo direcionado; pesos livres, quando atendem melhor às demandas de coordenação, controle e progressão desejadas; e exercícios com peso corporal, quando são adequados ao objetivo, ao nível de capacidade e à estrutura disponível. Nenhuma modalidade é superior em todas as situações: a escolha depende do contexto e da capacidade de gerar o estímulo necessário com segurança e consistência.\n\nA seleção deve equilibrar eficácia, viabilidade e aderência. Se um exercício provoca desconforto, exige uma técnica incompatível com o momento do aluno, não está disponível ou dificulta a progressão, deve ser reavaliado e, se necessário, substituído por uma alternativa que preserve o objetivo do movimento e o estímulo pretendido. A MOVIVO prioriza o que funciona melhor para cada pessoa, com critérios claros e espaço para adaptação ao longo do tempo.", "principles": "O treino de força da MOVIVO parte de princípios inegociáveis: individualização, segurança, progressão mensurável, qualidade de execução e consistência. Cada decisão deve considerar o objetivo, o nível de experiência, a disponibilidade, as limitações, a recuperação e a resposta individual ao treinamento. A progressão deve ser planejada e acompanhada por dados, respeitando a capacidade de adaptação de cada pessoa, sem confundir esforço com excesso ou intensidade com necessidade de treinar até a falha.\n\nO objetivo orienta o método; a evidência científica orienta as decisões. Volume, frequência, intensidade, proximidade da falha, seleção e ordem dos exercícios devem ser ajustados conforme a finalidade do treino, a experiência e a resposta do aluno. A MOVIVO adota padrões iniciais fundamentados em evidências, mas não transforma faixas de referência em regras universais. Exercícios, cargas e estratégias podem mudar; a lógica de treinamento e o propósito de cada escolha precisam permanecer claros.\n\nA melhor prescrição é aquela que produz progresso sustentável e pode ser mantida na prática. A MOVIVO acompanha desempenho, recuperação, dificuldades e adesão para realizar os menores ajustes necessários, sem reagir exageradamente a oscilações pontuais. Quando segurança, sintomas ou limitações exigirem avaliação profissional, a evolução do treino respeitará esses limites. O método é consistente nos princípios, flexível na aplicação e orientado por resultados individuais ao longo do tempo.", "specialPopulations": "A MOVIVO adapta a prescrição às necessidades e ao momento de cada aluno, sem aplicar os mesmos parâmetros a todos. Para o iniciante absoluto, a prioridade é desenvolver técnica, familiaridade com os exercícios e consistência, começando com um volume tolerável e progredindo gradualmente. No retorno após uma pausa, a carga de treino deve ser reajustada conforme a duração do afastamento, a condição atual e a capacidade recuperada, evitando tentar retomar imediatamente o nível anterior.\n\nPara pessoas em idade mais avançada, o treinamento deve considerar a experiência, a capacidade funcional, o equilíbrio, a mobilidade, a recuperação e eventuais limitações, valorizando força, autonomia e qualidade de vida. A idade, por si só, não determina a capacidade de treinar: a prescrição deve responder às condições e aos objetivos individuais. Diante de sintomas preocupantes ou situações que exijam avaliação clínica, a segurança prevalece sobre a progressão.\n\nNo treino em casa, a MOVIVO trabalha com os recursos disponíveis — peso corporal, halteres, elásticos ou outros equipamentos — para construir um programa viável e progressivo. A ausência de uma academia não deve impedir a evolução, mas exige escolhas coerentes com o material disponível, o espaço e a experiência do aluno. Em todos os casos, o princípio é o mesmo: adaptar o ponto de partida, respeitar a capacidade atual e progredir de forma segura e sustentável.", "substitutions": "As substituições na MOVIVO devem preservar o objetivo do exercício, o grupo muscular prioritário e a função que ele desempenha no programa. Sempre que possível, a alternativa deve manter o padrão de movimento, uma amplitude adequada e tolerável, além de um perfil de resistência compatível com o estímulo desejado ao longo da execução. Também devem ser considerados estabilidade, exigência técnica, conforto articular, equipamentos disponíveis e capacidade de progressão.\n\nSubstituir não significa apenas trocar um exercício por outro parecido. Duas opções que trabalham o mesmo grupo muscular podem oferecer estímulos diferentes devido à posição do corpo, à amplitude, à estabilidade e à forma como a resistência varia durante o movimento. Por isso, a MOVIVO deve selecionar a alternativa que melhor preserve o propósito original, sem exigir equivalência perfeita quando ela não for possível.\n\nApós a troca, cargas e repetições devem ser recalibradas conforme as características do novo exercício. A MOVIVO deve acompanhar a resposta do aluno e verificar se a substituição mantém a qualidade do estímulo, a segurança e a possibilidade de progressão. A ferramenta pode mudar; o objetivo do treinamento deve permanecer claro."}$mv$::jsonb, $mv${"periodization.blockWeeksByPhase.DELOAD.weeks": "Respaldo de artigo científico sobre o ciclo de deload"}$mv$::jsonb, $mv$Versão 1 (padrão do sistema). Atualização de metodologia baseado nos artigos cientificos$mv$, '[]'::jsonb, now()
WHERE NOT EXISTS (SELECT 1 FROM "methodology_documents" m WHERE m."domain" = 'STRENGTH');
